<script setup lang="ts">
import {ref,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,csrf} from '../api';import {useAuth} from '../stores/auth';import {Landmark,ShieldCheck} from 'lucide-vue-next';
const route=useRoute(),router=useRouter(),auth=useAuth(),busy=ref(false),error=ref(''),message=ref('');const form=ref({name:'',organization_name:'',email:'',password:'',password_confirmation:'',code:'',recovery_code:''});
const mode=computed(()=>route.path.slice(1));const title=computed(()=>({'login':'Welcome back','register':'Create your workspace','forgot-password':'Reset your password','reset-password':'Choose a new password','two-factor-challenge':'Two-factor verification','verify-email':'Verify your email','invitations/accept':'Join a workspace'}[mode.value]||'Sign in'));
async function submit(){busy.value=true;error.value='';message.value='';try{await csrf();if(mode.value==='verify-email'){await api('/api/auth/email/verification-notification','POST');message.value='Verification link sent. Open the local mail catcher for development.';return}if(mode.value==='invitations/accept'){await api('/api/invitations/accept','POST',{token:route.query.token});await auth.refresh();router.push('/');return}const endpoint=mode.value==='two-factor-challenge'?'two-factor-challenge':mode.value;const payload:any={...form.value};if(mode.value==='reset-password'){payload.token=route.query.token;payload.email=route.query.email||form.value.email}if(mode.value==='two-factor-challenge'){delete payload.email;delete payload.password;if(!payload.code)delete payload.code;if(!payload.recovery_code)delete payload.recovery_code}const d=await api('/api/auth/'+endpoint,'POST',payload);if(d?.two_factor){router.push('/two-factor-challenge');return}if(['forgot-password','reset-password'].includes(mode.value)){message.value=mode.value==='forgot-password'?'If the account exists, a reset link was sent to the configured mail catcher.':'Password updated. You can sign in.';return}await auth.refresh();router.push(auth.user?.email_verified_at?'/':'/verify-email')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function check(){await auth.refresh();if(auth.user?.email_verified_at)router.push('/')}
</script>
<template><div class="auth-card"><div class="auth-brand"><Landmark/> MortgageLens</div><span class="eyebrow">SECURE MORTGAGE WORKSPACE</span><h1>{{title}}</h1><p class="muted">Your files, your team, a clearer review process.</p><div class="alert error" v-if="error" role="alert">{{error}}</div><div class="alert success" v-if="message" role="status">{{message}}</div><form @submit.prevent="submit" class="form-stack"><template v-if="mode==='register'"><label>Full name<input v-model="form.name" required autocomplete="name" maxlength="120"/></label><label>Organization name<input v-model="form.organization_name" required maxlength="120"/></label></template><label v-if="['login','register','forgot-password','reset-password'].includes(mode)">Email address<input v-model="form.email" type="email" required autocomplete="email"/></label><label v-if="['login','register','reset-password'].includes(mode)">Password<input v-model="form.password" type="password" :minlength="mode==='login'?1:12" required :autocomplete="mode==='login'?'current-password':'new-password'"/></label><label v-if="['register','reset-password'].includes(mode)">Confirm password<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"/></label><template v-if="mode==='two-factor-challenge'"><label>Authenticator code<input v-model="form.code" inputmode="numeric" autocomplete="one-time-code" maxlength="6"/></label><p class="muted">Or use a single-use recovery code:</p><label>Recovery code<input v-model="form.recovery_code" autocomplete="off"/></label></template><template v-if="mode==='verify-email'"><ShieldCheck :size="40"/><p>Check the verification link in your email before accessing organization files.</p></template><p v-if="mode==='invitations/accept'">Accept this invitation for the email address you are currently signed in with. Membership never grants access to every file automatically.</p><button class="primary" :disabled="busy">{{busy?'Please wait…':mode==='verify-email'?'Send verification link':mode==='invitations/accept'?'Accept invitation':mode==='login'?'Sign in':mode==='register'?'Create account':mode==='two-factor-challenge'?'Verify':'Continue'}}</button></form><button v-if="mode==='verify-email'" class="secondary full" @click="check">I have verified my email</button><div class="auth-links"><RouterLink v-if="mode!=='login'" to="/login">Back to sign in</RouterLink><template v-else><RouterLink to="/forgot-password">Forgot password?</RouterLink><RouterLink to="/register">Create workspace</RouterLink></template></div><p class="micro">Phase 1: secure foundation. Analysis uses clearly labeled fictional samples only.</p></div></template>
